import{_ as a,o as r,c as e,a3 as o}from"./chunks/framework.Bh_aNVBG.js";const c=JSON.parse('{"title":"1. 서비스 개요","description":"","frontmatter":{},"headers":[],"relativePath":"partner/chapter-1.md","filePath":"partner/chapter-1.md"}'),n={name:"partner/chapter-1.md"};function p(s,t,l,i,h,d){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="_1-서비스-개요" tabindex="-1">1. 서비스 개요 <a class="header-anchor" href="#_1-서비스-개요" aria-label="Permalink to &quot;1. 서비스 개요&quot;">​</a></h1><h2 id="_1-1-서비스-소개" tabindex="-1">1.1. 서비스 소개 <a class="header-anchor" href="#_1-1-서비스-소개" aria-label="Permalink to &quot;1.1. 서비스 소개&quot;">​</a></h2><p><strong>인포디오(Infodio)</strong> 는 축제 및 행사 운영자가 방문객을 위한 안내 페이지를 구성하고 운영할 수 있도록 지원하는 플랫폼입니다.</p><p>파트너 계정은 행사 현장 운영을 지원하기 위한 계정으로, 할당된 프로젝트의 공지사항 관리 및 스탬프 투어 보상 지급 업무를 수행할 수 있습니다.</p><h2 id="_1-2-주요-기능" tabindex="-1">1.2. 주요 기능 <a class="header-anchor" href="#_1-2-주요-기능" aria-label="Permalink to &quot;1.2. 주요 기능&quot;">​</a></h2><p>파트너 계정에서 이용할 수 있는 주요 기능은 다음과 같습니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>설명</th></tr></thead><tbody><tr><td>공지사항</td><td>행사 운영과 관련된 공지사항을 등록하고 관리합니다.</td></tr><tr><td>스탬프 투어 보상 수령</td><td>방문객의 보상 수령 QR 코드를 스캔하여 보상 수령 여부를 확인하고 지급 업무를 진행합니다.</td></tr></tbody></table><h2 id="_1-3-서비스-구성" tabindex="-1">1.3. 서비스 구성 <a class="header-anchor" href="#_1-3-서비스-구성" aria-label="Permalink to &quot;1.3. 서비스 구성&quot;">​</a></h2><p>인포디오는 <strong>CMS(관리자 페이지)</strong> 와 <strong>방문객용 안내 페이지</strong>로 구성됩니다.</p><h3 id="_1-cms-관리자-페이지" tabindex="-1">① CMS(관리자 페이지) <a class="header-anchor" href="#_1-cms-관리자-페이지" aria-label="Permalink to &quot;① CMS(관리자 페이지)&quot;">​</a></h3><p>파트너가 할당된 프로젝트의 공지사항을 관리하고 스탬프 투어 보상 지급 업무를 수행하는 공간입니다.</p><p>파트너 계정에서는 다음과 같은 작업을 수행할 수 있습니다.</p><ul><li>공지사항 등록 및 관리</li><li>스탬프 투어 보상 수령 QR 코드 스캔</li></ul><h3 id="_2-방문객용-안내-페이지" tabindex="-1">② 방문객용 안내 페이지 <a class="header-anchor" href="#_2-방문객용-안내-페이지" aria-label="Permalink to &quot;② 방문객용 안내 페이지&quot;">​</a></h3><p>행사 정보와 각종 서비스를 방문객에게 제공하는 모바일 중심의 웹페이지입니다.</p><p>방문객은 별도의 앱 설치 없이 웹 브라우저를 통해 행사 정보를 확인하고 스탬프 투어에 참여할 수 있습니다.</p><p>파트너는 방문객용 안내 페이지에서 등록한 공지사항의 표시 상태를 확인할 수 있습니다.</p><h2 id="_1-4-서비스-이용-절차" tabindex="-1">1.4. 서비스 이용 절차 <a class="header-anchor" href="#_1-4-서비스-이용-절차" aria-label="Permalink to &quot;1.4. 서비스 이용 절차&quot;">​</a></h2><p>파트너 계정의 기본적인 이용 절차는 다음과 같습니다.</p><p><strong>STEP 1. CMS 접속 및 로그인</strong></p><p>프로젝트별로 제공된 CMS 접속 주소에 접속하여 발급받은 파트너 계정으로 CMS에 로그인합니다.</p><p>(예: <a href="https://infodio.kr/cms/?slug=2026smf" target="_blank" rel="noreferrer">https://infodio.kr/cms/?slug=2026smf</a>)</p><p><strong>STEP 2. 메뉴 선택</strong></p><p>수행할 업무에 따라 공지사항 또는 스탬프 투어 보상 수령 메뉴를 선택합니다.</p><p><strong>STEP 3. 현장 운영 업무 수행</strong></p><p>행사 운영에 필요한 공지사항을 등록하거나 방문객의 보상 수령 QR 코드를 스캔하여 보상 지급 업무를 진행합니다.</p><p><strong>STEP 4. 처리 결과 확인</strong></p><p>공지사항의 노출 상태 또는 보상 수령 처리 결과를 확인합니다.</p><h2 id="_1-5-사용자-매뉴얼-안내" tabindex="-1">1.5. 사용자 매뉴얼 안내 <a class="header-anchor" href="#_1-5-사용자-매뉴얼-안내" aria-label="Permalink to &quot;1.5. 사용자 매뉴얼 안내&quot;">​</a></h2><p>본 매뉴얼은 인포디오 파트너 계정을 이용하여 축제 및 행사 현장 운영 업무를 수행하는 사용자를 대상으로 작성되었습니다.</p><p>CMS 접속부터 공지사항 관리 및 스탬프 투어 보상 지급까지 주요 기능의 이용 방법을 단계별로 안내합니다.</p><p>각 기능별 설명은 다음과 같이 구성됩니다.</p><ul><li><strong>기능 소개:</strong> 해당 기능의 용도와 활용 방법</li><li><strong>이용 방법:</strong> 기능을 이용하는 단계별 절차</li><li><strong>화면 안내:</strong> 주요 화면 및 항목에 대한 설명</li><li><strong>참고 및 주의사항:</strong> 기능 이용 시 알아두어야 할 사항</li></ul><p>※ 본 매뉴얼의 화면 구성 및 기능은 서비스 업데이트에 따라 일부 변경될 수 있습니다.</p>',34)])])}const u=a(n,[["render",p]]);export{c as __pageData,u as default};
